using System;
using System.Collections.Generic;
using System.Diagnostics.Eventing.Reader;
using System.Linq;
using System.Text.RegularExpressions;
using System.Text;
using System.Windows;
using System.Windows.Controls;

namespace Aurora {
public sealed class SystemEventCase {
    public DateTime Time;public string Log,Provider,Message,Category,Cause,Advice,Repair;
    public int Id;public long? RecordId;
    public override string ToString(){return Time.ToString("dd/MM HH:mm")+"  •  "+Category+"  •  "+Provider+" ("+Id+")";}
}
public static class EventAnalysis {
    public static SystemEventCase Classify(string log,string provider,int id,DateTime time,long? recordId,string message){
        var item=new SystemEventCase{Log=log,Provider=provider??"",Id=id,Time=time,RecordId=recordId,Message=message??"",Category=L.T("Falha do sistema","System error"),Cause=L.T("O evento sozinho não determina a causa.","This event alone does not determine the cause."),Advice=L.T("Confira eventos próximos e o histórico de alterações antes de reparar.","Review nearby events and recent changes before repairing."),Repair=""};
        string p=item.Provider.ToLowerInvariant();
        if((p.Contains("kernel-power")&&id==41)||(p.Contains("eventlog")&&id==6008)){item.Category=L.T("Desligamento inesperado","Unexpected shutdown");item.Cause=L.T("Pode resultar de queda de energia, travamento, temperatura ou desligamento forçado; este evento não identifica qual.","Can follow power loss, a crash, heat or forced shutdown; this event does not identify which.");item.Advice=L.T("Confira temperaturas, alimentação, drivers e eventos anteriores ao horário indicado.","Check temperatures, power, drivers and events immediately before this time.");}
        else if(p.Contains("disk")||p.Contains("ntfs")||p.Contains("storahci")||p.Contains("stornvme")){item.Category=L.T("Armazenamento","Storage");item.Cause=L.T("Pode haver erro de leitura, sistema de arquivos, conexão ou dispositivo; o evento não confirma falha física.","May indicate a read, file-system, connection or device issue; it does not prove physical failure.");item.Advice=L.T("Faça backup dos dados importantes e confira SMART e os eventos da unidade antes de qualquer reparo.","Back up important data and review SMART and drive events before repair.");}
        else if(p.Contains("dns-client")&&id==1014){item.Category="DNS";item.Cause=L.T("A consulta expirou; pode ser rede, servidor DNS, VPN ou indisponibilidade temporária.","The query timed out; network, DNS server, VPN or a temporary outage are possible.");item.Advice=L.T("Teste a conexão e o DNS. Limpar o cache pode ajudar se houver registros antigos, mas não resolve falha do servidor.","Test connectivity and DNS. Flushing cache can help stale records but cannot fix a failing server.");item.Repair="dns-flush";}
        else if(p.Contains("windowsupdateclient")&&id==20){item.Category="Windows Update";item.Cause=L.T("Uma atualização falhou; o código no evento e o histórico de atualização ajudam a identificar o motivo.","An update failed; its error code and update history help identify the reason.");item.Advice=L.T("Confira o código de erro. Se o download estiver preso, redefina o cache de atualizações; para corrupção, use DISM e SFC.","Check the error code. Reset the update cache for a stuck download; use DISM and SFC for corruption.");item.Repair="windows-update";}
        else if(p.Contains("application error")&&id==1000){item.Category=L.T("Falha de aplicativo","Application crash");item.Cause=L.T("O aplicativo encerrou de modo inesperado; módulo com falha e exceção podem indicar a origem.","The app closed unexpectedly; the faulting module and exception may identify why.");item.Advice=L.T("Confira o módulo citado, atualize o aplicativo e verifique se a falha se repete.","Review the named module, update the app and check whether the crash repeats.");}
        else if(p.Contains(".net runtime")&&id==1026){item.Category=L.T("Falha de aplicativo .NET",".NET app failure");item.Cause=L.T("O aplicativo registrou uma exceção não tratada. Pode ser defeito no aplicativo, dependência ou dados de entrada.","The app recorded an unhandled exception. The app, a dependency or input data may be responsible.");item.Advice=L.T("Confira o nome e a versão do aplicativo e da exceção. Atualize o aplicativo; revise a biblioteca .NET exigida sem instalar versões aleatórias.","Check the app name, version and exception. Update the app; review its required .NET runtime rather than installing arbitrary versions.");item.Repair="runtimes";}
        else if(p.Contains("sidebyside")&&(id==33||id==59)){item.Category=L.T("Dependência de aplicativo","App dependency");item.Cause=L.T("A configuração lado a lado de um aplicativo não pôde ser carregada; pode faltar uma biblioteca específica.","An app's side-by-side configuration could not be loaded; a specific runtime may be missing.");item.Advice=L.T("Identifique no evento o assembly e a arquitetura exigidos. Instale a biblioteca correspondente na área de componentes.","Identify the required assembly and architecture in the event. Install the matching runtime in Components.");item.Repair="runtimes";}
        else if(p.Contains("resource-exhaustion")&&id==2004){item.Category=L.T("Pressão de memória","Memory pressure");item.Cause=L.T("O Windows registrou falta de memória virtual e pode listar os maiores consumidores.","Windows recorded low virtual memory and may list the largest consumers.");item.Advice=L.T("Analise os processos e mantenha o arquivo de paginação gerenciado pelo sistema. Compare o consumo ao longo do uso.","Review processes and keep system-managed paging. Compare consumption over normal usage.");item.Repair="memory-review";}
        else if(p.Contains("whea-logger")){item.Category=L.T("Sinal de hardware ou firmware","Hardware or firmware signal");item.Cause=L.T("O Windows registrou um erro de hardware corrigido ou não corrigido; o componente é indicado nos detalhes.","Windows recorded a corrected or uncorrected hardware error; details identify the component.");item.Advice=L.T("Revise os detalhes, temperaturas, alimentação e firmware do fabricante. Não há reparo de software único para este evento.","Review details, temperatures, power and manufacturer firmware. There is no single software repair for this event.");}
        else if(p.Contains("printservice")&&(id==372||id==808)){item.Category=L.T("Falha de impressão","Printing failure");item.Cause=L.T("A impressão ou o carregamento de um componente de impressão falhou.","Printing or loading a print component failed.");item.Advice=L.T("Confira a impressora e o driver indicados. Reiniciar o spooler pode recuperar um serviço travado, mas não corrige um driver incompatível.","Check the indicated printer and driver. Restarting the spooler may recover a stalled service, but cannot fix an incompatible driver.");item.Repair="spooler";}
        else if(p.Contains("service control manager")&&(id==7023||id==7031||id==7034)){item.Category=L.T("Serviço interrompido","Service stopped");item.Cause=L.T("O serviço falhou ou encerrou; a dependência ou o próprio serviço pode estar com problema.","The service failed or stopped; a dependency or the service itself may be at fault.");item.Advice=L.T("Confira o nome do serviço e eventos próximos. Evite reiniciar serviços desconhecidos automaticamente.","Check the service name and nearby events. Avoid restarting unknown services automatically.");if(item.Message.IndexOf("Spooler",StringComparison.OrdinalIgnoreCase)>=0)item.Repair="spooler";}
        if((p.Contains("windowsupdateclient")||p.Contains("servicing")||p.Contains("cbs"))&&Regex.IsMatch(item.Message,@"\b0x(?:80073712|80073701|800f0831|800f081f|8007371b|80070570)\b",RegexOptions.IgnoreCase)){
            item.Category=L.T("Componentes do Windows","Windows components");item.Cause=L.T("O código registrado indica arquivos ou componentes ausentes, inconsistentes ou corrompidos.","The recorded code indicates missing, inconsistent or corrupt files or components.");item.Advice=L.T("Execute DISM RestoreHealth e depois SFC. Se faltar a origem de reparo, selecione uma mídia compatível em Reparo do sistema.","Run DISM RestoreHealth followed by SFC. If a repair source is missing, select compatible media in System repair.");item.Repair="components";
        }
        return item;
    }
    public static string SearchUrl(SystemEventCase item){if(item==null)throw new ArgumentNullException("item");string codes=String.Join(" ",Regex.Matches(item.Message??"",@"\b0x[0-9a-f]{8}\b",RegexOptions.IgnoreCase).Cast<Match>().Select(x=>x.Value).Distinct().Take(3));return "https://www.bing.com/search?q="+Uri.EscapeDataString("site:learn.microsoft.com OR site:support.microsoft.com "+item.Provider+" Event "+item.Id+" "+codes);}
    public static List<SystemEventCase> Read(int days,int perLog){
        var result=new List<SystemEventCase>();string query="*[System[(Level=1 or Level=2) and TimeCreated[timediff(@SystemTime) <= "+(days*86400000L)+"]]]";
        foreach(string log in new[]{"System","Application"}){
            try{var q=new EventLogQuery(log,PathType.LogName,query){ReverseDirection=true};using(var reader=new EventLogReader(q))for(int i=0;i<perLog;i++){using(EventRecord record=reader.ReadEvent()){if(record==null)break;string message="";try{message=record.FormatDescription()??"";}catch{}if(message.Length>3000)message=message.Substring(0,3000);result.Add(Classify(log,record.ProviderName,record.Id,record.TimeCreated??DateTime.MinValue,record.RecordId,message));}}}
            catch(Exception e){result.Add(Classify(log,"OuO",0,DateTime.Now,null,L.T("Não foi possível ler o log: ","Could not read log: ")+e.Message));}
        }
        return result.OrderByDescending(x=>x.Time).ToList();
    }
    public static string Recommendations(IEnumerable<SystemEventCase> events){var list=events.ToList();StringBuilder text=new StringBuilder();int shutdown=list.Count(x=>x.Category==L.T("Desligamento inesperado","Unexpected shutdown")),disk=list.Count(x=>x.Category==L.T("Armazenamento","Storage")),updates=list.Count(x=>x.Category=="Windows Update"),crashes=list.Count(x=>x.Category==L.T("Falha de aplicativo","Application crash"));
        if(disk>0)text.AppendLine(L.T("• Eventos de armazenamento: faça backup e confira a saúde da unidade.","• Storage events: back up data and check drive health."));
        if(shutdown>0)text.AppendLine(L.T("• Desligamentos inesperados: investigue energia, temperaturas e eventos anteriores.","• Unexpected shutdowns: review power, temperatures and preceding events."));
        if(updates>0)text.AppendLine(L.T("• Falhas de atualização: confira códigos de erro e o histórico do Windows Update.","• Update failures: check error codes and Windows Update history."));
        if(crashes>0)text.AppendLine(L.T("• Falhas de aplicativos: identifique módulos recorrentes e versões instaladas.","• Application crashes: identify recurring modules and installed versions."));
        if(text.Length==0)text.AppendLine(L.T("Nenhum padrão conhecido encontrado nos eventos lidos. Isso não prova ausência de problemas.","No known pattern found in readable events. This does not prove the system is problem-free."));
        return text.ToString();
    }
}
public partial class MainWindow {
    bool stabilityNoticeShown;
    void StabilityPage(){Heading(T("Estabilidade e eventos","Stability & events"),T("Falhas recentes organizadas por tipo, com hipóteses e ações verificáveis.","Recent failures grouped by type, with hypotheses and verifiable actions."));BeginColumns(2);
        var overview=Card(T("Monitor de estabilidade","Stability monitor"),T("Lê erros dos últimos 14 dias nos logs Sistema e Aplicativo. Eventos próximos podem estar relacionados, mas proximidade não prova causa.","Reads errors from the last 14 days in System and Application logs. Nearby events may be related, but timing alone does not prove cause."));
        TextBlock summary=Text(T("Clique em Analisar eventos para começar.","Select Analyze events to begin."),13,Muted);overview.Children.Add(summary);
        var categoryFilter=new ComboBox{Margin=new Thickness(0,0,0,8),Visibility=Visibility.Collapsed};categoryFilter.Items.Add(T("Todos os tipos","All categories"));categoryFilter.SelectedIndex=0;overview.Children.Add(categoryFilter);
        ListBox list=new ListBox{Height=330,Background=Surface,Foreground=Ink,BorderBrush=Muted,Visibility=Visibility.Collapsed};overview.Children.Add(list);
        List<SystemEventCase> loadedCases=new List<SystemEventCase>();Action showCases=()=>{string chosen=categoryFilter.SelectedIndex<=0?null:Convert.ToString(categoryFilter.SelectedItem);list.Items.Clear();foreach(var item in loadedCases.Where(x=>chosen==null||x.Category==chosen))list.Items.Add(item);list.Visibility=list.Items.Count>0?Visibility.Visible:Visibility.Collapsed;categoryFilter.Visibility=loadedCases.Count>0?Visibility.Visible:Visibility.Collapsed;};categoryFilter.SelectionChanged+=(s,e)=>{if(showCases!=null)showCases();};
        var detail=Card(T("Caso selecionado","Selected case"),T("Hipóteses não são diagnóstico definitivo. Revise o evento antes de iniciar qualquer reparo.","Hypotheses are not a definitive diagnosis. Review the event before starting a repair."));detail.Visibility=Visibility.Collapsed;TextBox report=Input("");report.Height=235;report.IsReadOnly=true;report.Foreground=StateGreen;report.TextChanged+=(sender,args)=>report.Foreground=OutcomeBrush(report.Text);report.AcceptsReturn=true;report.TextWrapping=TextWrapping.Wrap;report.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;detail.Children.Add(report);
        Button repairButton=null;TextBlock actionHint=Text("",12,Muted);detail.Children.Add(actionHint);
        list.SelectionChanged+=(s,e)=>{var item=list.SelectedItem as SystemEventCase;if(item==null){detail.Visibility=Visibility.Collapsed;if(repairButton!=null)repairButton.IsEnabled=false;return;}detail.Visibility=Visibility.Visible;report.Text=item.Time+"\n"+item.Log+" • "+item.Provider+" • "+item.Id+"\n\n"+T("Possível causa: ","Possible cause: ")+item.Cause+"\n\n"+T("Como investigar: ","How to investigate: ")+item.Advice+"\n\n"+item.Message;
            bool actionable=new[]{"dns-flush","windows-update","spooler","components"}.Contains(item.Repair);if(repairButton!=null){repairButton.IsEnabled=actionable;repairButton.Content=item.Repair=="dns-flush"?T("Limpar cache DNS","Flush DNS cache"):item.Repair=="windows-update"?T("Redefinir Windows Update","Reset Windows Update"):item.Repair=="spooler"?T("Reiniciar spooler","Restart spooler"):item.Repair=="components"?T("Reparar componentes e arquivos","Repair components and files"):item.Repair=="runtimes"?T("Revisar bibliotecas exigidas","Review required runtimes"):item.Repair=="memory-review"?T("Analisar consumo de memória","Analyze memory usage"):T("Sem reparo automático","No automatic repair");}
            actionHint.Text=actionable?T("Revise a ação proposta. O evento antigo continuará no histórico; observe se a falha volta a ocorrer.","Review the proposed action. The old event remains in history; watch for recurrence."):T("Este evento não identifica uma correção automática confiável. Use o diagnóstico indicado acima.","This event does not identify a reliable automatic fix. Use the guidance above.");
        };
        Button analyze=Button(T("Analisar eventos","Analyze events"),()=>{List<SystemEventCase> cases=null;Work("Windows events",()=>{cases=EventAnalysis.Read(14,120);return EventAnalysis.Recommendations(cases);},r=>{summary.Text=r;summary.Foreground=ResultTone.IsFailure(r)?OutcomeBrush(r):StateGreen;loadedCases=cases??new List<SystemEventCase>();categoryFilter.Items.Clear();categoryFilter.Items.Add(T("Todos os tipos","All categories"));foreach(string category in loadedCases.Select(x=>x.Category).Distinct().OrderBy(x=>x))categoryFilter.Items.Add(category);categoryFilter.SelectedIndex=0;showCases();});});
        Row(overview,analyze,Button(T("Abrir Monitor de Confiabilidade","Open Reliability Monitor"),()=>{try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("perfmon.exe","/rel"){UseShellExecute=true});}catch(Exception error){ShowNotice(error.Message);}}));
        repairButton=Button(T("Selecione um caso","Select a case"),()=>{var item=list.SelectedItem as SystemEventCase;if(item==null)return;
            if(item.Repair=="runtimes"||item.Repair=="memory-review")return;
            if(item.Repair=="dns-flush"){
                if(!Confirm(T("Limpar o cache DNS para investigar esta falha? O histórico de eventos não será apagado.","Flush DNS cache to investigate this failure? Event history will remain.")))return;
                Work(T("Limpar cache DNS","Flush DNS cache"),()=>Describe(Runner.Run("ipconfig.exe","/flushdns",30000)),r=>report.Text=r+"\n"+T("Observe se surgem novos eventos DNS após esta ação.","Watch for new DNS events after this action."));return;
            }
            if(item.Repair=="components"){
                RunRepairs(machine!=null&&machine.Build>=9200?new[]{RepairPlans.Dism("RestoreHealth",null,null,"1",false),new RepairCommand{Title="SFC",File="sfc.exe",Arguments="/scannow"}}:new[]{new RepairCommand{Title="SFC",File="sfc.exe",Arguments="/scannow"}},report);return;
            }
            if(item.Repair=="windows-update"){
                if(!RequireAdmin()||!Confirm(T("Guardar o cache atual e redefinir o Windows Update para investigar esta falha?","Back up current cache and reset Windows Update to investigate this failure?")))return;
                Work("Reset Windows Update",()=>WindowsMaintenance.ResetUpdateCache(),r=>report.Text=r);return;
            }
            if(item.Repair=="spooler"){
                if(!RequireAdmin()||!Confirm(T("Reiniciar o serviço de impressão para investigar esta falha?","Restart the print service to investigate this failure?")))return;
                Work("Restart spooler",()=>Describe(Runner.PS("Restart-Service Spooler -ErrorAction Stop; Get-Service Spooler | Select-Object Status | Format-List",60000)),r=>report.Text=r);return;
            }
        });repairButton.IsEnabled=false;
        Row(detail,repairButton,Button(T("Pesquisar orientação oficial","Search official guidance"),()=>{var item=list.SelectedItem as SystemEventCase;if(item!=null)Open(EventAnalysis.SearchUrl(item));}));
        var guide=Card(T("Como usar esta análise","How to use this analysis"),T("Selecione um erro para ver a causa provável e a ação disponível. O OuO só oferece reparo direto quando o evento aponta para uma rotina conhecida.","Select an error to see a likely cause and available action. OuO offers direct repair only when an event matches a known routine."));
        Note(guide,"Desligamento inesperado: verifique energia e temperaturas. Armazenamento: faça backup antes de testar a unidade. Falha de aplicativo: compare versão, módulo com falha e atualizações. Um evento isolado não prova a causa.","Unexpected shutdown: check power and temperatures. Storage: back up before testing the drive. App crash: review the version, faulting module and updates. A single event does not prove the cause.");
        if(!preview&&!stabilityNoticeShown){stabilityNoticeShown=true;Dispatcher.BeginInvoke(new Action(()=>ShowToast(T("Área de diagnóstico: revise o evento e a ação proposta antes de executar reparos.","Diagnostic area: review the event and proposed action before running repairs."))));}

        if(!preview)Dispatcher.BeginInvoke(new Action(()=>analyze.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent))));
    }
    void RecommendationCenter(){var card=Card(T("Centro de recomendações","Recommendation center"),T("Prioriza sinais observáveis e apresenta orientações para revisão.","Prioritizes observable signals and presents guidance for review."));TextBlock notes=Text(T("Analise eventos recentes para receber sugestões.","Analyze recent events for suggestions."),13,StateGreen);card.Children.Add(notes);Row(card,Button(T("Analisar agora","Analyze now"),()=>{Work("Recommendations",()=>EventAnalysis.Recommendations(EventAnalysis.Read(14,80)),r=>notes.Text=r);}));}
}
}
